from typing import Dict, List

def demo_conservation() -> None:
    n = 5
    V = list(range(n))
    adj = {v: [u for u in V if u != v] for v in V}
    patterns = [
        {0: 1, 1: 0, 2: 0, 3: 0, 4: 0},
        {v: v for v in V},
        {0: 3, 1: -2, 2: 7, 3: -5, 4: 1},
        {v: 4 for v in V},
    ]
    for f in patterns:
        lap = {v: sum(f[v] - f[u] for u in adj[v]) for v in V}
        assert sum(lap.values()) == 0
        print(f, '->', lap, 'deg =', sum(lap.values()))

if __name__ == '__main__':
    demo_conservation()

