function LAPLACIAN(f, vertices, adjacency):
    D <- empty divisor
    for each vertex v in vertices:
        s <- 0
        for each neighbor u of v in adjacency:
            s <- s + (f[v] - f[u])
        D[v] <- s
    return D

function VERIFY_DEGREE_ZERO(f, vertices, adjacency):
    D <- LAPLACIAN(f, vertices, adjacency)
    total <- sum of D[v] over all v
    return (total == 0)

